#!/bin/bash
# Generated by tools/gen.py from package.toml - edit package.toml instead.

PT_NAME=flatout2-wine-gog
PT_ID=flatout2
PT_TARGET=/opt/flatout2
PT_STEAM_APPID=''
PT_REMOVE=()
PT_ALIASES=()
PT_EXTRA_PATHS=()
PT_ICON_NAME=''
PT_NO_DATA=
PT_GBE_LIBS=()

pt_fetch() {
    f=$(pt_need_source setup_flatout2_2.1.0.9.exe )
    rm -rf "$PT_WORK/x-setup_flatout2_2.1.0.9.exe"; pt_extract inno "$f" "$PT_WORK/x-setup_flatout2_2.1.0.9.exe"
    install -d "$PT_GAME/"; cp -a "$PT_WORK/x-setup_flatout2_2.1.0.9.exe/game/." "$PT_GAME/"
}

pt_icon() {
    local i; for i in "$PT_GAME"/goggame-*.ico; do pt_icon_from_ico "$i"; break; done
}

# pkgtool.sh - shared build logic for generated game/data packages.
#
# tools/gen.py prepends the package's settings (PT_* variables and pt_post_*
# hook functions from package.toml) and writes the result as build.sh into the
# package directory. PKGBUILD, RPM spec and debian/rules all run:
#
#   PT_SRCDIR=<dir with source files> PT_WORK=<scratch dir> bash build.sh prepare
#   PT_SRCDIR=... PT_WORK=... bash build.sh install <destdir>
#   bash build.sh deb-split <destdir> <first part destdir pattern>   (Debian only)
#
# Game data that can't be downloaded anonymously:
#   Steam:  PT_CACHE/<pkgname>/steam-<appid>/ (filled by tools/fetch-steam) is
#           used if present; otherwise steamcmd runs with STEAM_USER, prompting
#           on a terminal.
#   GOG/Humble installers: looked up in PT_SRCDIR, then PT_CACHE/<pkgname>/,
#           then PT_CACHE/.
# Master copy: tools/pkgtool.sh in jm2/linux-packages. Do not edit build.sh.

set -euo pipefail
shopt -s nullglob dotglob

pt_die()  { printf '==> ERROR (%s): %s\n' "$PT_NAME" "$*" >&2; exit 1; }
pt_msg()  { printf '==> %s\n' "$*" >&2; }
pt_msg2() { printf '  -> %s\n' "$*" >&2; }

: "${PT_SRCDIR:?PT_SRCDIR must point at the directory holding the source files}"
: "${PT_WORK:?PT_WORK must point at a scratch directory}"
PT_CACHE=${PT_CACHE:-${TMPDIR:-/var/tmp}/linux-packages-cache}
PT_GAME=$PT_WORK/game          # assembled game tree
PT_META=$PT_WORK/meta          # icon, interfaces, notes

# ------------------------------------------------------------ sources ----

pt_find_source() { # <filename> -> path
    local c
    for c in "$PT_SRCDIR/$1" "$PT_CACHE/$PT_NAME/$1" "$PT_CACHE/$1"; do
        [ -e "$c" ] && { readlink -f "$c"; return 0; }
    done
    return 1
}

pt_need_source() {
    pt_find_source "$1" || pt_die "missing source file '$1'. ${2:-Download it and place it in $PT_SRCDIR or $PT_CACHE/$PT_NAME/.}"
}

pt_steam_fetch() { # <appid> <platform> <depot specs...> -> prints install dir
    local appid=$1 platform=$2; shift 2
    local cached=$PT_CACHE/$PT_NAME/steam-$appid
    if [ -d "$cached" ] && [ -n "$(ls -A "$cached")" ]; then
        pt_msg2 "using cached Steam download $cached"
        printf '%s\n' "$cached"; return 0
    fi
    command -v steamcmd >/dev/null 2>&1 || pt_die "steamcmd is not installed and no cached download exists in $cached (see tools/fetch-steam)"
    local user=${STEAM_USER:-}
    if [ -z "$user" ]; then
        [ -t 0 ] || pt_die "set STEAM_USER, or pre-fetch with tools/fetch-steam $PT_NAME"
        printf 'Steam username: ' >&2; read -r user
    fi
    local dir=$PT_WORK/steam-$appid args=() spec
    mkdir -p "$dir"
    for spec in "$@"; do args+=("+download_depot ${spec/:/ }"); done
    pt_msg2 "downloading app $appid ($platform) with steamcmd as $user"
    steamcmd +@sSteamCmdForcePlatformType "$platform" +@ShutdownOnFailedCommand 1 \
        +force_install_dir "$dir" +login "$user" "+app_update $appid validate" "${args[@]}" +quit >&2 ||
        pt_die "steamcmd failed"
    # download_depot ignores force_install_dir; merge depots into the app dir.
    for spec in "$@"; do
        local app=${spec%%:*} depot=${spec#*:} found= p
        for p in "$dir/steamapps/content/app_$app/depot_$depot" \
                 "$HOME/.steam/steamcmd/linux32/steamapps/content/app_$app/depot_$depot" \
                 "$HOME/.local/share/Steam/steamcmd/linux32/steamapps/content/app_$app/depot_$depot" \
                 "$HOME/.steam/steam/steamapps/content/app_$app/depot_$depot" \
                 "$HOME/Steam/steamapps/content/app_$app/depot_$depot"; do
            [ -d "$p" ] && { cp -rn "$p/." "$dir/"; found=1; break; }
        done
        [ -n "$found" ] || pt_die "depot $depot of app $app was not found after download"
    done
    printf '%s\n' "$dir"
}

pt_extract() { # <kind> <file> <dest>
    local kind=$1 f=$2 dest=$3
    mkdir -p "$dest"
    case $kind in
        inno)    innoextract -q -s --gog -d "$dest" "$f" ;;
        mojo)    # GOG Linux installers: makeself stub + zip; unzip warns about the stub.
                 unzip -qo "$f" -d "$dest" || [ $? -eq 1 ] ;;
        zip)     unzip -qo "$f" -d "$dest" ;;
        7z|tar)  bsdtar -xf "$f" -C "$dest" ;;
        iso)     bsdtar -xf "$f" -C "$dest" ;;
        makeself) sh "$f" --noexec --nox11 --target "$dest" >/dev/null ;;
        copy)    cp -a "$f" "$dest/" ;;
        *)       pt_die "unknown extract kind '$kind'" ;;
    esac
}

# -------------------------------------------------------------- icons ----

pt_png_size() { # prints WIDTH of a PNG
    od -An -tu1 -j16 -N4 "$1" | awk '{print $1*16777216+$2*65536+$3*256+$4}'
}

pt_icon_from_exe() { # <exe> -> $PT_META/icon.png (largest image)
    local exe=$1 tmp=$PT_WORK/icons best= bw=0 f w
    mkdir -p "$tmp" "$PT_META"
    wrestool -x -t 14 -o "$tmp" "$exe" 2>/dev/null || true
    for f in "$tmp"/*.ico; do icotool -x -o "$tmp" "$f" 2>/dev/null || true; done
    for f in "$tmp"/*.png; do
        w=$(pt_png_size "$f"); [ "$w" -gt "$bw" ] && { bw=$w; best=$f; }
    done
    [ -n "$best" ] || { pt_msg2 "no icon found in ${exe##*/}"; return 0; }
    cp "$best" "$PT_META/icon.png"
}

pt_icon_from_ico() {
    local tmp=$PT_WORK/icons best= bw=0 f w
    mkdir -p "$tmp" "$PT_META"
    icotool -x -o "$tmp" "$1" 2>/dev/null || true
    for f in "$tmp"/*.png; do
        w=$(pt_png_size "$f"); [ "$w" -gt "$bw" ] && { bw=$w; best=$f; }
    done
    [ -n "$best" ] && cp "$best" "$PT_META/icon.png"
    return 0
}

pt_icon_install() { # <destdir>
    [ -f "$PT_META/icon.png" ] || return 0
    local w; w=$(pt_png_size "$PT_META/icon.png")
    case $w in 16|22|24|32|48|64|96|128|192|256|512) ;; *) w=256 ;; esac
    install -Dm644 "$PT_META/icon.png" "$1/usr/share/icons/hicolor/${w}x${w}/apps/${PT_ICON_NAME:-$PT_ID}.png"
}

# --------------------------------------------------------------- gbe -----

pt_gbe_present() { # "?lib" entries are optional; prints the libs that exist
    local rel
    for rel in "${PT_GBE_LIBS[@]}"; do
        if [ "${rel#\?}" != "$rel" ]; then
            [ -f "$PT_GAME/${rel#\?}" ] && printf '%s\n' "${rel#\?}"
        else
            [ -f "$PT_GAME/$rel" ] || pt_die "Goldberg: $rel not found in the game files"
            printf '%s\n' "$rel"
        fi
    done
}

pt_gbe_interfaces() { # original libs (relative to game root) -> $PT_META/interfaces/<lib>.txt
    local rel
    pt_gbe_present > "$PT_META/gbe-libs"
    while read -r rel; do
        command -v gbe-steam-interfaces >/dev/null 2>&1 || pt_die "gbe-fork-bin is required at build time"
        mkdir -p "$PT_META/interfaces/$rel"
        gbe-steam-interfaces "$PT_GAME/$rel" "$PT_META/interfaces/$rel"
    done < "$PT_META/gbe-libs"
}

pt_gbe_apply() { # <installed game root>
    local root=$1 rel lib emu dir
    while read -r rel; do
        lib=${rel##*/} dir=$root/$(dirname "$rel")
        case $lib in
            steam_api64.dll) emu=win/x64/steam_api64.dll ;;
            steam_api.dll)   emu=win/x86/steam_api.dll ;;
            libsteam_api.so) emu=linux/$PT_GBE_LINUX_ARCH/libsteam_api.so ;;
            *) pt_die "Goldberg: don't know how to replace $lib" ;;
        esac
        [ "${PT_GBE_FLAVOUR:-regular}" = experimental ] && emu=${emu/#win\//win-experimental/} && emu=${emu/#linux\//linux-experimental/}
        rm -f "$dir/$lib"
        ln -s "/usr/lib/gbe-fork/$emu" "$dir/$lib"
        install -d "$dir/steam_settings"
        install -m644 "$PT_META/interfaces/$rel/steam_interfaces.txt" "$dir/steam_settings/steam_interfaces.txt"
        printf '%s\n' "$PT_STEAM_APPID" > "$dir/steam_settings/steam_appid.txt"
        printf '%s\n' "$PT_STEAM_APPID" > "$dir/steam_appid.txt"
        # Package-provided settings, shipped flat as gbe.<file> (makepkg sources
        # can't be directories): gbe.configs.app.ini -> steam_settings/configs.app.ini
        local s
        for s in "$PT_SRCDIR"/gbe.*; do
            install -m644 "$s" "$dir/steam_settings/${s##*/gbe.}"
        done
        find "$dir/steam_settings" -type f -exec chmod 644 {} +
    done < "$PT_META/gbe-libs"
}

# ------------------------------------------------------------ install ----

pt_remove_globs() { # <root> <globs...>
    local root=$1 g f; shift
    for g in "$@"; do
        for f in "$root"/$g; do rm -rf -- "$f"; done
    done
}

pt_launcher() { # <destdir>: /usr/bin/<id> + gamelaunch config
    local d=$1
    install -Dm644 "$PT_SRCDIR/$PT_ID.conf" "$d/usr/share/gamelaunch/games/$PT_ID.conf"
    install -d "$d/usr/bin"
    printf '#!/bin/sh\nexec gamelaunch %s "$@"\n' "$PT_ID" > "$d/usr/bin/$PT_ID"
    chmod 755 "$d/usr/bin/$PT_ID"
    local alias
    for alias in "${PT_ALIASES[@]}"; do ln -s "$PT_ID" "$d/usr/bin/$alias"; done
    install -Dm644 "$PT_SRCDIR/$PT_ID.desktop" "$d/usr/share/applications/$PT_ID.desktop"
}

pt_docs() {
    local d=$1/usr/share/doc/$PT_NAME
    install -Dm644 "$PT_SRCDIR/README.md" "$d/README.md"
}

pt_files_list() { # <destdir> -> $PT_WORK/files.list (RPM %files -f)
    local d=$1
    (
        cd "$d"
        [ -n "${PT_TARGET:-}" ] && [ -z "${PT_NO_DATA:-}" ] && printf '%s/\n' "$PT_TARGET"
        [ -n "${PT_ID:-}" ] && [ -f "usr/bin/$PT_ID" ] && {
            printf '/usr/bin/%s\n' "$PT_ID"
            for a in "${PT_ALIASES[@]}"; do printf '/usr/bin/%s\n' "$a"; done
            printf '/usr/share/gamelaunch/games/%s.conf\n/usr/share/applications/%s.desktop\n' "$PT_ID" "$PT_ID"
        }
        if [ -d usr/share/icons ]; then
            find usr/share/icons -name "${PT_ICON_NAME:-$PT_ID}.png" | sed 's|^|/|'
        fi
        [ -d "usr/share/doc/$PT_NAME" ] && printf '%%doc /usr/share/doc/%s\n' "$PT_NAME"
        for x in "${PT_EXTRA_PATHS[@]}"; do printf '%s\n' "$x"; done
    ) > "$PT_WORK/files.list"
}

# ------------------------------------------------------------- stages ----

pt_prepare() {
    rm -rf "$PT_GAME" "$PT_META"
    mkdir -p "$PT_GAME" "$PT_META"
    pt_msg "assembling $PT_NAME"
    pt_fetch          # generated: steam/gog/hib/url -> $PT_GAME
    declare -F pt_post_prepare >/dev/null && (cd "$PT_GAME" && pt_post_prepare)
    pt_icon           # generated
    [ "${#PT_GBE_LIBS[@]}" -gt 0 ] && pt_gbe_interfaces
    return 0
}

pt_install() {
    local d=${1:?usage: build.sh install <destdir>}
    # Hooks run inside the game tree, so $D must be absolute (debian passes
    # debian/<pkg>).
    mkdir -p "$d"; d=$(cd "$d" && pwd)
    [ -d "$PT_GAME" ] || pt_die "run 'build.sh prepare' first"
    if [ -n "${PT_TARGET:-}" ] && [ -z "${PT_NO_DATA:-}" ]; then
        local root=$d$PT_TARGET
        pt_msg "installing to $PT_TARGET"
        install -d "$root"
        cp -a --no-preserve=ownership "$PT_GAME/." "$root/"
        pt_remove_globs "$root" "${PT_REMOVE[@]}"
        [ "${#PT_GBE_LIBS[@]}" -gt 0 ] && pt_gbe_apply "$root"
        declare -F pt_post_install >/dev/null && (cd "$root" && D=$d pt_post_install)
        # Normalise permissions: the tree is read-only shared data.
        find "$root" -type d -exec chmod 755 {} +
        find "$root" -type f ! -perm -u+x -exec chmod 644 {} +
        find "$root" -type f -perm -u+x -exec chmod 755 {} +
        [ -n "${PT_ID:-}" ] && date -u +%s > "$root/.gamelaunch-stamp"
    fi
    [ -n "${PT_ID:-}" ] && pt_launcher "$d"
    [ -n "${PT_ID:-}${PT_ICON_NAME:-}" ] && pt_icon_install "$d"
    pt_docs "$d"
    pt_files_list "$d"
}

# Move files into N Debian part packages so no .deb exceeds the ar member
# size limit (~9.3 GiB). Greedy by size, largest first.
pt_deb_split() { # <main destdir> <part dir prefix> <parts>
    local main=$1 prefix=$2 n=$3 limit=$(( 9 * 1024 * 1024 * 1024 ))
    local -a used; local i
    for (( i=1; i<=n; i++ )); do used[i]=0; done
    (cd "$main" && find ".${PT_TARGET}" -type f -printf '%s %p\n') | sort -rn |
    while read -r size path; do
        local best=1
        for (( i=2; i<=n; i++ )); do [ "${used[i]}" -lt "${used[best]}" ] && best=$i; done
        [ $(( used[best] + size )) -le "$limit" ] || pt_die "data does not fit in $n Debian parts; raise [deb] parts in package.toml"
        used[best]=$(( used[best] + size ))
        install -d "$prefix$best/$(dirname "$path")"
        mv "$main/$path" "$prefix$best/$path"
    done
}

case ${1:-} in
    prepare)   pt_prepare ;;
    install)   pt_install "${2:-}" ;;
    deb-split) pt_deb_split "$2" "$3" "$4" ;;
    *)         echo "usage: build.sh prepare | install <destdir> | deb-split <main> <prefix> <n>" >&2; exit 2 ;;
esac
